CREATE TABLE IF NOT EXISTS audit_entries(id BIGSERIAL PRIMARY KEY,actor_user_id BIGINT,action VARCHAR(80) NOT NULL,entity_type VARCHAR(60) NOT NULL,entity_id VARCHAR(80),details VARCHAR(1000),occurred_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_entries(entity_type,entity_id); CREATE INDEX IF NOT EXISTS idx_audit_actor ON audit_entries(actor_user_id);
